const lockRestoreTargetName = `-- name: LockRestoreTargetName :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// LockRestoreTargetName serializes restore requests for one target
// database (or one connection's globals) until the transaction ends.
func (q *Queries) LockRestoreTargetName(ctx context.Context, lockKey string) error {
	_, err := q.db.Exec(ctx, lockRestoreTargetName, lockKey)
	return err
}

