const takeRestoreIdentityHandoff = `-- name: TakeRestoreIdentityHandoff :one
DELETE FROM restore_identity_handoff WHERE restore_id = $1
RETURNING sealed_identity, (expires_at > now())::boolean AS valid
`

type TakeRestoreIdentityHandoffRow struct {
	SealedIdentity []byte `json:"sealedIdentity"`
	Valid          bool   `json:"valid"`
}

// TakeRestoreIdentityHandoff deletes the handoff of a restore and returns
// it: an identity is read at most once. valid is false when it had
// expired.
func (q *Queries) TakeRestoreIdentityHandoff(ctx context.Context, restoreID uuid.UUID) (TakeRestoreIdentityHandoffRow, error) {
	row := q.db.QueryRow(ctx, takeRestoreIdentityHandoff, restoreID)
	var i TakeRestoreIdentityHandoffRow
	err := row.Scan(&i.SealedIdentity, &i.Valid)
	return i, err
}
